    assert private.text_blocked_by(v_case.text, v_list) = v_case.blocked,
      format('fixture case %s should be blocked: %s', v_case.n, v_case.blocked);
    assert private.text_is_blocked(v_case.text) = v_case.blocked,
      format('fixture case %s through text_is_blocked', v_case.n);
  end loop;
  for v_case in
    select w.word, w.n
      from unnest(array['when', 'then', 'hence', 'Chennai', 'shenanigans', 'Stephen', 'phenomenon', 'Athens', 'henna', 'whence', 'thence', 'kitchen', 'Henry', 'henchman', 'orbit', 'absorb', 'sorbet', 'morbid', 'forbid', 'corbel', 'orbital', 'carrot', 'parrot', 'rotate', 'protein', 'rotten', 'trot', 'grotto', 'Rotterdam', 'Dorothy', 'protest', 'prototype', 'frothy', 'throttle', 'wrote', 'rotunda', 'protagonist', 'rotor', 'star', 'start', 'guitar', 'target', 'tart', 'altar', 'nectar', 'avatar', 'Qatar', 'tartan', 'mortar', 'tarot', 'starling', 'tarmac', 'stare', 'tardy', 'custard', 'mustard', 'Gibraltar', 'panel', 'company', 'panda', 'panic', 'expand', 'spaniel', 'Japan', 'pancake', 'pantry', 'panorama', 'pandemic', 'companion', 'rampant', 'pantomime', 'Pandora', 'panther', 'Panama', 'span', 'saucepan', 'kitten', 'skit', 'kite', 'kitsch', 'kitty', 'skittle', 'Nikita', 'giant', 'plant', 'antique', 'elephant', 'want', 'pleasant', 'peasant', 'constant', 'distant', 'antelope', 'antenna', 'anthem', 'Atlantic', 'gigantic', 'fantastic', 'infant', 'servant', 'merchant', 'tenant', 'radiant', 'brilliant', 'important', 'mantis', 'Antarctica', 'banter', 'chant', 'enchant', 'slant', 'grant', 'pant', 'frame', 'ramp', 'program', 'tram', 'gram', 'cram', 'dramatic', 'Ramadan', 'grammar', 'parameter', 'ramble', 'rampart', 'scramble', 'diagram', 'telegram', 'pyramid', 'ceramic', 'Bertram', 'ramen']::text[]) with ordinality as w (word, n)
  loop
    assert not private.text_blocked_by(v_case.word, v_list),
      format('innocent word %s (%s) was blocked', v_case.n, v_case.word);
  end loop;
end
$$;
